package data

import android.media.AudioAttributes
import android.media.SoundPool


/**
 * Plays the app's short procedural sound effects. The WAVs are still
 * generated by [SoundLibrary] (identical waveforms to the desktop build),
 * but playback goes through Android's [SoundPool] instead of
 * `javax.sound.sampled`, so rapid taps don't starve the audio mixer.
 *
 * Best-effort everywhere: a muted app, a device without audio, a failed
 * sample load or a released pool all become silent no-ops.
 */
object SoundManager {

    private const val MAX_STREAMS = 4

    private var pool: SoundPool? = null
    private var initialised = false

    /** Event → SoundPool sample id, filled as each sample finishes loading. */
    private val sampleIds = mutableMapOf<SoundEvent, Int>()
    private val loadRequests = mutableMapOf<Int, SoundEvent>()


    /**
     * Generates the WAVs (if absent) and loads them into a [SoundPool].
     * Idempotent; failures leave the app silent rather than crashing.
     */
    fun init() {
        if (initialised) return
        initialised = true
        runCatching {
            SoundLibrary.ensureGenerated()
            val soundPool = SoundPool.Builder()
                .setMaxStreams(MAX_STREAMS)
                .setAudioAttributes(
                    AudioAttributes.Builder()
                        .setUsage(AudioAttributes.USAGE_ASSISTANCE_SONIFICATION)
                        .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                        .build()
                )
                .build()
            soundPool.setOnLoadCompleteListener { _, sampleId, status ->
                val event = loadRequests[sampleId] ?: return@setOnLoadCompleteListener
                if (status == 0) sampleIds[event] = sampleId
            }
            SoundEvent.entries.forEach { event ->
                val file = SoundLibrary.pathFor(event).toFile()
                if (!file.isFile) return@forEach
                val id = soundPool.load(file.absolutePath, 1)
                if (id > 0) loadRequests[id] = event
            }
            pool = soundPool
        }
    }


    /**
     * Plays [event] at the user-configured volume. Returns immediately;
     * the mixer thread does the work. No-op when sound is muted, the
     * volume is 0, or the sample hasn't finished loading.
     */
    fun play(event: SoundEvent) {
        if (!initialised) return
        if (!SettingsManager.soundEffectsEnabled) return
        val volume = SettingsManager.soundVolume.coerceIn(0, 100) / 100f
        if (volume <= 0f) return
        val soundPool = pool ?: return
        val sampleId = sampleIds[event] ?: return
        runCatching {
            soundPool.play(sampleId, volume, volume, 1, 0, 1f)
        }
    }


    fun shutdown() {
        runCatching { pool?.release() }
        pool = null
        sampleIds.clear()
        loadRequests.clear()
        initialised = false
    }


    /** Number of loaded samples for [event] — 0 or 1 on Android. */
    @Suppress("unused")
    fun debugPoolSize(event: SoundEvent): Int =
        if (sampleIds.containsKey(event)) 1 else 0
}
